import React from "react";
import { Table } from "react-bootstrap";

const RiskCategory = ({ riskCategories = [] }) => {

    return (
        <div>
            {/* Table Section */}
            <Table responsive className="table table-nowrap mb-0">
                <thead className="text-white bg-dark">
                    <tr>
                        <th className="text-white">Datetime</th>
                        <th className="text-white">Type</th>
                        <th className="text-white">Code</th>
                        <th className="text-white">Description</th>
                        <th className="text-white">Value</th>
                    </tr>
                </thead>
                <tbody>
                    {riskCategories?.length === 0 ? (
                        <tr>
                            <td colSpan="5" className="fw-bold text-center">
                                No Risk Category/Assessment available
                            </td>
                        </tr>
                    ) : (
                        riskCategories?.map((risk, index) => (
                            <tr key={index}>
                                <td>{risk?.datetime}</td>
                                <td>{risk?.type}</td>
                                <td>{risk?.code}</td>
                                <td>{risk?.description}</td>
                                <td>{risk?.value}</td>
                            </tr>
                        ))
                    )}
                </tbody>
            </Table>
        </div>
    );
};

export default RiskCategory;
